WITH base AS (SELECT *, FLOOR(amount) AS amount_whole FROM payments WHERE paid_at >= '2025-09-27' AND method = 'card'), summary AS (SELECT CASE WHEN amount_whole >= 62 THEN 'high' WHEN amount_whole >= 27 THEN 'mid' ELSE 'low' END AS amount_whole_bucket, AVG(amount_whole) AS avg_amount_whole FROM base GROUP BY CASE WHEN amount_whole >= 62 THEN 'high' WHEN amount_whole >= 27 THEN 'mid' ELSE 'low' END) SELECT amount_whole_bucket, avg_amount_whole FROM summary;
